# Extra depth for guide articles: key-facts box, additional sections, per-article FAQs.
# Facts limited to established official rules - no prices, no invented figures.
ARTICLE_EXTRAS = {
'how-to-apply-saudi-evisa-step-by-step': {'mins': 7, 'facts': ['Eligibility follows your passport, not your address - check the route first', 'Name and passport number must match the passport character for character', 'The mandatory medical insurance is issued with the eVisa itself', 'Every traveller, children included, needs their own application and visa'], 'faq': [('How long does the whole application take to complete?', 'The form itself takes a few minutes when your documents are beside you. Most delays come from re-doing photos and correcting passport details - both are avoidable with ten minutes of preparation.'), ('Do I need hotel or flight bookings to apply?', 'No. Neither is required for the tourist eVisa application. Book freely once the visa is issued.'), ('What should I check when the eVisa arrives?', 'Your name, passport number and the validity dates on the issued document itself. That document - not the confirmation email - is what the border officer reads.')]},
'saudi-visa-for-us-uk-schengen-visa-holders': {'mins': 6, 'facts': ['The visa must be a valid US, UK or Schengen tourist or business visa', 'It must have been used - entered on at least once - to open the Saudi route', 'Permanent residents of the US, UK or EU are covered by the same arrangement', 'Airlines verify the conditions at check-in, before you ever reach Saudi Arabia'], 'faq': [('My Schengen visa is brand new and unused. Can I fly to Saudi?', 'Not on this route. The visa must have been used to enter the Schengen area at least once. Take that trip first, or apply through another route you qualify for.'), ('Is it better to apply in advance or get the visa on arrival?', 'Applying in advance. The assessment then happens before you travel, and you board with the visa issued - on arrival, the decision happens at the border with your whole trip depending on it.'), ('My US visa is in my old passport. Does it still count?', 'Usually yes, travelling with both passports - but tell us in advance so your exact case is confirmed before you book.')]},
'alula-travel-guide': {'mins': 6, 'facts': ["Hegra was Saudi Arabia's first UNESCO World Heritage site", 'Hegra entry runs on timed tours - book before you fly', 'AlUla airport (ULH) has flights from Riyadh, Jeddah and Dubai', 'The season runs October to March; desert nights are cold'], 'faq': [('How many days do I need in AlUla?', 'Two nights minimum, three if you can. Hegra, Elephant Rock, the Old Town and Maraya each deserve unhurried time, and the distances between sites are real.'), ('Can I combine AlUla with Madinah?', 'Yes - roughly four hours by road separates them, and the pairing is popular. Muslim travellers combine Umrah in Madinah with AlUla sightseeing on the same trip.'), ('Do I need a special visa for AlUla?', 'No. AlUla is standard tourism on the Saudi tourist eVisa.')]},
'abha-asir-travel-guide': {'mins': 6, 'facts': ['Abha sits above 2,200 metres; Al Soudah peaks pass 3,000 metres', 'Summer brings cloud and rain while the rest of the Kingdom bakes', "Rijal Almaa's stone towers are edged with white quartz patterns", 'Abha airport (AHB) is an official eVisa entry airport'], 'faq': [('When is the best time to visit Abha?', "June to September for the green, misty season - book ahead, it is Saudi's own summer escape. Winter is clear and crisp, and cold at night."), ('Is Abha very different from Riyadh or Jeddah?', 'Completely - mountain climate, juniper forest, its own painted art tradition and a slower pace. Pack a layer in any month.'), ('Do I need anything beyond my eVisa for Asir?', 'No - it is ordinary domestic tourism once you are in the Kingdom. A hire car is close to essential for the mountain roads.')]},
'dammam-eastern-province-guide': {'mins': 6, 'facts': ['Dammam, Khobar and Dhahran form one Gulf-coast tri-city', 'The King Fahd Causeway runs 25 km from Khobar to Bahrain', "Ithra in Dhahran is the region's landmark cultural centre", 'King Fahd International (DMM) is a main eVisa entry airport'], 'faq': [('Can I day-trip to Bahrain from Khobar?', 'Yes, over the King Fahd Causeway - but it is a real border crossing: it ends that Saudi stay, and returning uses another entry on a multiple-entry visa.'), ('What is the best season for the Eastern Province?', 'October to March. Summer on the Gulf coast is hot and very humid.'), ('Is the Eastern Province worth a stop on a Saudi tour?', 'Yes - for the Corniche cities, Half Moon Bay and Ithra alone, and it pairs naturally with a Gulf itinerary through DMM airport.')]},
'makkah-guide-for-umrah-pilgrims': {'mins': 7, 'facts': ['Makkah is open to Muslims only - checkpoints enforce it on every road', 'The tourist eVisa covers Umrah outside the Hajj season', 'Umrah and Rawdah slots are booked in the Nusuk app', 'The Haramain train links Jeddah airport, Makkah and Madinah'], 'faq': [('Can a non-Muslim visit Makkah as a tourist?', "No. Makkah is closed to non-Muslims without exception. Non-Muslim travellers can visit Madinah's public areas outside the Prophet's Mosque, Jeddah, Riyadh and the rest of the Kingdom."), ('Should I use an Umrah visa or the tourist eVisa?', 'Both are legitimate for Umrah outside Hajj season. The tourist eVisa adds the freedom to tour the Kingdom on the same trip; the Umrah visa is the traditional pilgrim route. Either way, Hajj needs the official Hajj visa.'), ('How do I get from Jeddah airport to Makkah?', 'The Haramain train from the airport station reaches Makkah in well under an hour and is the calmest option. Coaches and taxis cover the same route at every price level - agree taxi fares in advance.')]},
'saudi-90-day-multiple-entry-visa': {'mins': 6, 'facts': ['There is no official Saudi visa class you can pick off a shelf called “90-day multiple entry”', 'The tourist eVisa is one product: 1 year, multiple entry, 90 days per visit, 180 days per year', 'Validity (entry window) and stay (days inside) are different numbers - both are printed on the issued visa', 'Agency package names describe their service fee, not a different government visa'], 'faq': [('Is there an official Saudi 90-day multiple entry visa?', 'Not as a selectable class. Eligible nationalities are issued the one-year multiple-entry tourist eVisa (90-day stays, 180 days per year in total); some nationalities receive single-entry 30-day visas. ‘90-day’ offers are agency packages - ask what visa will actually be issued, in writing.'), ('What is the difference between validity and stay?', 'Validity is the window in which you may enter; stay is how long you may remain once inside. Both are printed on your issued visa, and the tourist eVisa also carries a 180-day annual ceiling.'), ('A 90-day package was quoted cheaper. Is it a good deal?', 'It can be - a smaller service fee for the same government process is a fair deal. It is only a problem if the provider cannot confirm, in writing and before payment, which visa class will be issued and what validity it will carry.')]},
'saudi-visa-for-pakistani-citizens': {'mins': 7, 'facts': ['A Pakistani passport alone is not eVisa-eligible - beware any site selling one against it', 'GCC residency (UAE, Qatar, Kuwait, Bahrain, Oman) opens the eVisa route', 'A used US, UK or Schengen visa opens assessment for visa on arrival', 'Family visits run on a host-sponsored invitation started inside Saudi Arabia'], 'faq': [('Can Pakistanis get a Saudi eVisa?', 'Not on the passport alone - Pakistan is not on the 72-country list. Pakistanis qualify through GCC residency, through a used US, UK or Schengen visa at the border, through a sponsored visit visa, or through the Umrah system.'), ('I live in Dubai on a work visa. Which route is mine?', 'The GCC-resident route. With a passport valid six months and UAE residency valid three months, you apply for the standard tourist eVisa - one year, multiple entries.'), ('Can I visit my brother in Riyadh?', 'Yes - on a family visit visa that your brother sponsors from inside Saudi Arabia. He obtains the approved invitation first; your application attaches to it.')]},
'saudi-visa-for-filipino-citizens': {'mins': 7, 'facts': ['The Philippines is not on the 72-country eVisa list', 'Filipinos resident in a GCC country qualify for the eVisa through residency', 'Family visits to relatives working in Saudi run on host sponsorship', 'Saudi work visas are employer-led only - never a product sold to the worker'], 'faq': [('Can a Filipino get a Saudi tourist eVisa?', 'Not against the passport alone. Filipino citizens qualify through GCC residency, may be assessed on arrival with a used US, UK or Schengen visa, visit family on a sponsored visa, or travel for Umrah through the official Umrah channels.'), ('My sister works in Jeddah. How do I visit her?', 'Through a family visit visa: your sister arranges the approved invitation from inside Saudi Arabia, and you apply against it in advance.'), ('An agent offered me a Saudi work visa for a fee. Is that real?', 'No. Employment visas are processed by the hiring company through official channels. A work visa sold directly to the worker is a classic scam pattern.')]},
'saudi-visa-for-egyptian-citizens': {'mins': 7, 'facts': ['Egypt is not on the 72-country Saudi eVisa list', 'Egyptians resident in the Gulf qualify for the eVisa through residency', 'The profession condition for GCC residents was abolished', 'Family visits run on an invitation your host obtains inside Saudi Arabia'], 'faq': [('Can Egyptians apply for the Saudi eVisa?', 'Not on the passport alone. Egyptians qualify through GCC residency, through a used US, UK or Schengen visa on arrival, through a sponsored family or personal visit visa, or through the Umrah system.'), ('I work in the UAE. Can I do Umrah on the eVisa?', 'Yes. Apply through the GCC-resident route; the tourist eVisa covers Umrah outside the Hajj season, with slots booked in the Nusuk app.'), ('How do I visit my son who works in Riyadh?', 'On a family visit visa sponsored by your son from inside Saudi Arabia - he secures the invitation first, then your application follows.')]},
'saudi-visa-for-bangladeshi-citizens': {'mins': 7, 'facts': ['Bangladesh is not on the 72-country Saudi eVisa list', 'GCC residency opens the eVisa: passport 6+ months, residency 3+ months', 'Family visits are sponsored by your host inside Saudi Arabia', 'Work visas are employer-led through official channels only'], 'faq': [('Can Bangladeshis get a Saudi eVisa?', 'Not on the passport alone. The working routes are GCC residency, a used US, UK or Schengen visa assessed on arrival, a host-sponsored visit visa, or the official Umrah channels.'), ('I live in Qatar. Which visa do I apply for?', 'The standard tourist eVisa, through the GCC-resident route - one year, multiple entries, up to 90 days a visit, Umrah included outside Hajj season.'), ('Someone offered to sell me a Saudi work visa. Should I pay?', 'No. Saudi employment visas are processed by the employer through official channels in both countries. A visa sold to the worker is a warning sign.')]},
'saudi-evisa-for-uk-citizens': {'mins': 6, 'facts': ['UK citizens are on the 72-country eVisa list', 'One year, multiple entries, up to 90 days per visit, 180 days per year in total', 'Umrah is included outside Hajj season - slots are booked in Nusuk', 'Visa on arrival exists as a backup, but the advance eVisa is the safer plan'], 'faq': [('Do UK citizens need a visa for Saudi Arabia?', 'Yes - but you qualify for the eVisa online: one year, multiple entries, 90 days per visit. Apply before you fly and arrival becomes a formality.'), ('Can I perform Umrah on the tourist eVisa?', 'Yes, outside the Hajj season. Book your Umrah and Rawdah slots in the Nusuk app after the visa is issued. Hajj itself always uses the official Hajj route.'), ('I have two passports. Which do I use?', 'Apply on your British passport and travel on the same one - the eVisa is attached to that passport number.')]},
'visiting-madinah-city-guide': {'mins': 8, 'facts': ['The Prophet’s Mosque’s courtyard umbrellas open at dawn and fold at night', 'Rawdah visits are by timed Nusuk permit - book as soon as dates are fixed', 'Quba Mosque, ten minutes south, is the first mosque founded in Islam', 'The Haramain train reaches Madinah in about two hours from Jeddah airport'], 'faq': [('Can non-Muslims visit Madinah?', 'Yes - the city is open to all visitors. The Prophet’s Mosque itself is reserved for Muslim worshippers, so non-Muslims explore the rest of the city: museums, markets and historic sites, dressed modestly.'), ('How many days do I need in Madinah?', 'Two full days cover the mosque, Quba, Uhud and the markets without rushing. Pilgrims often stay longer - the city rewards slowness.'), ('How do I book the Rawdah?', 'Through the Nusuk app, with a timed permit tied to your passport. Slots release in batches and go quickly in peak seasons, so book the moment your travel dates are certain.')]},
'haramain-train-guide': {'mins': 7, 'facts': ['Makkah to Madinah in around two and a quarter hours at up to 300 km/h', 'Jeddah’s station sits inside King Abdulaziz International Airport Terminal 1', 'Book ahead for Fridays, Ramadan and Umrah peaks - trains sell out', 'Luggage is airline-style: one larger bag plus hand luggage, checked at the gate'], 'faq': [('How do I book the Haramain train?', 'Through the official Haramain website or app, using your passport details. Book as early as your dates allow - peak trains sell out days ahead.'), ('Is the train good for Umrah trips?', 'It is the easiest option: off the plane at Jeddah into the airport’s own station, then direct to Makkah or Madinah without a highway transfer.'), ('How early should I arrive?', 'Treat it like a flight: 30 to 45 minutes before departure, more in Ramadan and peak Umrah season. Gates close well before the train leaves.')]},
'travelling-to-saudi-arabia-as-a-woman': {'mins': 7, 'facts': ['No abaya or headscarf is legally required for visiting women in public', 'A headscarf is needed for entering mosques - carry a light one', 'Women may perform Umrah without a mahram', 'Women have driven in Saudi Arabia since 2018 and rent cars normally'], 'faq': [('Can a woman travel to Saudi Arabia alone?', 'Yes. Solo women visitors are routine: you can hold the visa in your own name, check into hotels alone, drive, and travel between cities unaccompanied.'), ('Do I have to wear an abaya?', 'No. Modest dress - shoulders and knees covered, nothing sheer or figure-hugging - is the working rule in public. Mosques are the exception: cover your hair to enter.'), ('Can I do Umrah without a mahram?', 'Yes. Women may perform Umrah without a mahram, and permits in the Nusuk app are issued to you individually.')]},
'driving-in-saudi-arabia': {'mins': 7, 'facts': ['Visitors drive on many national licences; an IDP alongside removes rental-desk arguments', 'Speed limits are camera-enforced everywhere - fines reach you via the rental company', 'Camels on desert highways at dawn and dusk are the serious road risk', 'Riyadh to Jeddah is nearly 950 km - fly it or split it, don’t sprint it'], 'faq': [('Can tourists rent a car in Saudi Arabia?', 'Yes - with your passport, visa, driving licence (an International Driving Permit helps) and a payment card. Minimum age is usually 21, and 25 for larger cars.'), ('Is it safe to drive between cities?', 'The highways are excellent. The real risks are distance, fatigue and camels at dawn and dusk - plan fuel and rest stops, keep the tank above half, and slow down at camel-warning signs.'), ('Can women rent and drive cars?', 'Yes, on exactly the same terms as men. Women have held Saudi licences since 2018.')]},
'visiting-saudi-arabia-during-ramadan': {'mins': 7, 'facts': ['The country inverts its day: quiet afternoons, cities alive until suhoor', 'Non-fasters eat and drink discreetly in public during daylight - hotels serve guests all day', 'Makkah and Madinah peak in the last ten nights; book everything early', 'Eid al-Fitr closes the month with festival days and full hotels'], 'faq': [('Can I eat during the day in Ramadan as a visitor?', 'Yes - in your hotel and in the screened or takeaway arrangements many restaurants run. In public, eat and drink discreetly out of courtesy to those fasting.'), ('Is Ramadan a bad time to visit?', 'For culture and atmosphere it may be the best month of the year - iftar nights are unforgettable. For a packed daytime sightseeing schedule, pick another month.'), ('What should I say in Ramadan?', '“Ramadan Kareem” is the greeting you will hear everywhere. Reply “Ramadan Mubarak” and you will be met with a smile.')]},
'saudi-multiple-entry-visa-uae-residents': {'mins': 7, 'facts': ['UAE residents qualify through the GCC-resident route - residency, not nationality, opens it', 'The visa issued is one year, multiple entry, up to 90 days per visit', 'Stays across the year are capped at 180 days in total', 'Passport needs 6+ months and the Emirates ID 3+ months at application'], 'faq': [('Do I choose single or multiple entry when I apply?', 'There is nothing to choose. The tourist eVisa issued to eligible applicants, including GCC residents, is a one-year multiple-entry visa by default.'), ('Can I enter Saudi Arabia by road from the UAE?', 'Yes. The eVisa is valid at land borders as well as airports, including the Al Batha crossing used for the drive towards Riyadh.'), ('My Emirates ID expires in two months. Can I still apply?', 'Not safely - residency must be valid for at least three months when you apply. Renew the residency first, then apply for the visa.')]},
'saudi-stopover-visa-guide': {'mins': 6, 'facts': ['Up to 96 hours (four days), single entry, tied to a connecting Saudia or flynas booking', 'Issued inside the airline booking flow - there is no separate application site', 'Umrah is permitted on it outside the Hajj season, with Nusuk booking for slots', 'It cannot be extended and does not replace the tourist eVisa for real trips'], 'faq': [('Is the stopover visa really free?', 'There is no embassy visa fee. A modest insurance and administration amount may be included in the booking total and is shown before you pay - if a third-party site charges a large stopover visa fee, you are not buying the official product.'), ('Can I leave the airport on a stopover visa?', 'Yes - that is its purpose. You can enter the Kingdom for up to 96 hours, visit the city and even perform Umrah outside Hajj season, then take your onward flight.'), ('Can I get a stopover visa without a flight booking?', 'No. It is issued as part of a qualifying Saudia or flynas booking with a Saudi layover. Travelling to Saudi Arabia as your destination needs the tourist eVisa or another visa.')]},
'best-places-to-visit-in-saudi-arabia': {'mins': 8, 'facts': ["Hegra in AlUla is the Nabataeans' second city - over 100 carved tombs, timed entry", "Diriyah's At-Turaif is the original Saudi capital and a UNESCO site", "Jeddah's Al-Balad old town is built from Red Sea coral stone", "Madinah's sacred centre is open to Muslim visitors only"], 'faq': [('How many days do I need for a first trip?', 'Seven to ten days covers the classic arc comfortably: Riyadh and Diriyah, AlUla, then Jeddah - flying between them. Five days works if you drop one stop rather than rushing all three.'), ('Is AlUla worth the effort to reach?', 'Yes - it is the single place travellers rate above expectation most consistently. There are direct flights from Riyadh and Jeddah, and two days is the right minimum.'), ('Can non-Muslims visit Madinah?', "Non-Muslims cannot enter the central sacred area around the Prophet's Mosque. The city is a pilgrimage destination rather than a general tourism stop; Makkah is closed to non-Muslims entirely.")]},
'saudi-arabia-cultural-etiquette': {'mins': 7, 'facts': ['Visitor women are not required to wear an abaya or headscarf outside mosques', 'Shops may pause briefly at prayer times - it lasts minutes', 'Shake the coffee cup gently to signal you have had enough qahwa', 'Alcohol is fully prohibited, including for tourists'], 'faq': [('Do I have to cover my hair as a woman visiting?', 'Not in public generally. You will need a headscarf to enter mosques, and loose modest clothing everywhere. Many visitors carry one light scarf and use it as needed.'), ('Can I take photos of people?', 'Ask first, especially with women and families, and never photograph people praying at close range or anything military or governmental. Landscapes and architecture are unrestricted in normal tourist areas.'), ('What happens during Ramadan for visitors?', 'Muslims fast in daylight; eating and drinking discreetly is the polite approach, restaurants often open at sunset for iftar, and the evenings are the social peak. It is a fascinating time to visit if you plan around the rhythm.')]},
'best-time-to-visit-saudi-arabia': {'mins': 7, 'facts': ['Peak sightseeing season: November to February', "Asir's highlands stay in the 20s even in August - the local summer escape", 'Ramadan moves about 11 days earlier each Gregorian year', 'Tourist eVisas do not cover the Hajj period in Makkah'], 'faq': [('When is it cheapest to go?', 'The hot months outside Ramadan and school holidays - roughly May to September in the cities - bring the lowest flight and hotel prices, traded against serious heat.'), ('Is winter actually cold?', 'In Riyadh and the desert, nights can drop close to freezing and AlUla evenings need a real jacket. Jeddah stays mild. Pack layers, not a beach-only bag.'), ('When is Umrah busiest?', 'Ramadan is the peak, followed by the winter school holidays. The quietest Umrah weeks are usually just after Hajj season and in the hottest months.')]},
'visiting-riyadh-city-guide': {'mins': 7, 'facts': ["The Riyadh Metro's six lines opened in phases from late 2024", 'The National Museum is the best two-hour orientation in the country', 'Diriyah is a separate city 20 minutes north-west - plan it as its own half-day', "Kingdom Centre's Sky Bridge sits 99 floors up"], 'faq': [('How do I get around Riyadh?', "The metro for the spine of the city, ride-hailing apps for everything else. Driving yourself is possible but the city's scale and traffic make it the least relaxing option for a short visit."), ('How long do I need in Riyadh?', 'Two full days for the essentials (museum, old town, Diriyah, one modern district), three if the Boulevard City season is running and you want an evening of it.'), ('Is Riyadh worth it, or just a stopover?', 'Consistently the surprise of the trip for visitors who give it days rather than hours - a huge, changing capital with its founding city preserved beside it.')]},
'visiting-jeddah-city-guide': {'mins': 7, 'facts': ["Al-Balad's houses are built from coral stone with wooden rawashin balconies", 'The King Fahd Fountain is the tallest of its kind in the world at over 300m', 'The Haramain train reaches Makkah in about an hour from Jeddah airport', "Jeddah has been Makkah's port and pilgrim gateway for over 1,000 years"], 'faq': [('Can I swim in Jeddah?', 'Yes - at the private beach clubs of Obhur Al Janoubia north of the centre, which have the facilities and the reefs nearby. Public Corniche areas are for promenading rather than swimming.'), ('Is Jeddah a good base for Umrah?', 'Very. Many pilgrims overnight in Jeddah on arrival or departure, and the airport train makes Makkah about an hour away. Madinah is under two hours by the same line.'), ('What should I eat first?', "Sayadiyah - the Hijazi spiced rice with fried fish - then a mutabbaq from an Al-Balad stall for the street-level version of the city's cooking.")]},
'what-to-pack-for-saudi-arabia': {'mins': 6, 'facts': ['Plugs are Type G - the same as the UAE and UK', 'Prescription medicines: original packaging plus the prescription itself', 'A headscarf is needed for women entering mosques', 'Desert nights and Saudi air-conditioning both require one warm layer'], 'faq': [('Do I need an abaya in my bag?', 'Not required for visitors. Many women pack one loose over-layer anyway for mosques and conservative settings - it is the most useful single garment on the trip.'), ('Can I bring my regular medication?', "Usually, with the paperwork: original packaging, trip-appropriate quantity, and your prescription or a doctor's letter. Controlled categories need checking against the SFDA lists before you fly - see our prohibited items guide."), ('What adapter do I need?', 'Type G (three square pins), identical to the UK and UAE. US and EU travellers need an adapter; almost nobody else does.')]},
'saudi-arabian-food-guide': {'mins': 7, 'facts': ['Kabsa and jareesh are recognised as Saudi national dishes', "Refill etiquette: shake the qahwa cup slightly to say 'enough'", "Sayadiyah is the Hijaz's signature fish-and-rice plate", 'Al-Ahsa grows dates in one of the largest oases on earth'], 'faq': [('What is the one dish I must try?', 'Kabsa for the national canon - then mandi if you find a place cooking it in a pit. In Jeddah, make it sayadiyah instead; geography outranks canon at the coast.'), ('Is the food spicy?', 'Fragrant more than fiery: cardamom, black lime, cinnamon and saffron do the work, with chilli usually arriving as a sauce on the side (shatta) that you control yourself.'), ('What about vegetarians?', 'Workable and improving: foul, falafel, lentil soups, salads, rice dishes and the bakery repertoire carry most days, and city restaurants increasingly mark vegetarian options clearly.')]},
'prohibited-items-saudi-arabia': {'mins': 6, 'facts': ['No alcohol allowance exists at all - not even duty-free', 'Controlled medicines need the prescription carried with them', 'Drones without prior aviation approval are routinely confiscated', 'Drug offences carry among the most severe penalties in the world'], 'faq': [('Can I bring wine as a gift for a friend?', 'No. Alcohol is prohibited for everyone in all quantities, gifts included. It will be confiscated and can create serious trouble - bring dates instead; it is also the better gift locally.'), ('My medication is legal at home. Is it fine?', "Not automatically. Check the specific drug against the Saudi Food and Drug Authority's controlled lists, and travel with the prescription and original packaging regardless."), ('Can I fly my drone for holiday photos?', 'Only with prior approval from the aviation authority, arranged before travel. Without it, expect confiscation at the border - most visitors simply leave it home.')]},
'how-to-check-your-saudi-evisa-status': {'mins': 6, 'facts': ['Applications filed with us are tracked on this site with the VSA- reference and passport number', 'Embassy and platform visas can be verified on the official MOFA visa search', "Most waiting time is spent in the 'with the authority' stage - that is the normal queue", 'Count working days: the Saudi weekend is Friday and Saturday'], 'faq': [('My tracking has not moved for days. Is something wrong?', "Usually not. Most of the processing time is spent in the single 'with the authority' stage, and weekends and official holidays pause progress. If a document is needed, it will be requested through us - you will not be left guessing."), ('The authority issued my visa but I have no email. What now?', 'Search your inbox and spam for the passport number first. If you applied through us, the issued document is also downloadable from the tracking page itself, so the email is a copy, not the only copy.'), ('Can an airline check my eVisa?', 'Yes. Airlines verify the visa record at check-in against your passport, which is one reason the passport number on the application must be exact.')]},
'umrah-visa-from-dubai': {'mins': 7, 'facts': ['Most UAE residents perform Umrah on the tourist eVisa - no separate Umrah visa needed', 'GCC residents need 6+ months on the passport and 3+ months on the residency', 'Umrah and Rawdah slots are booked separately in the Nusuk app', 'The Haramain train links Jeddah airport, Makkah and Madinah'], 'faq': [('I live in Dubai on a work visa. Which visa do I need for Umrah?', 'Almost certainly the GCC-resident tourist eVisa: your UAE residency qualifies you, and the eVisa covers Umrah outside Hajj season. Check your passport has six months and your residency three months remaining.'), ('I am visiting Dubai on a tourist visa. Can I do Umrah from here?', 'The GCC-resident route needs residency, not a visit visa. Your route is either the standard eVisa if your passport is eligible, or the dedicated Umrah visa through approved channels - ask us and we will route you.'), ('When should I book Nusuk permits?', 'As soon as the visa is issued. Ramadan and holiday slots go first, and each traveller needs their own permits registered in the app.')]},
'saudi-evisa-for-us-citizens': {'mins': 6, 'facts': ['US citizens are on the 72-country eVisa list', 'One year, multiple entries, up to 90 days per visit, 180 days per year in total', 'Visa on arrival exists as a backup, but the advance eVisa is the better plan', 'Umrah is included outside Hajj season; paid work is not allowed'], 'faq': [('Can I just get the visa when I land?', 'Yes, US citizens qualify for visa on arrival. We still recommend the eVisa in advance: same visa, no airport queue, and the airline can verify you before you fly.'), ('I renewed my passport. Is my eVisa still valid?', 'No. The eVisa is issued against a specific passport; a new passport means a new visa, even if the old visa had months left.'), ('Can I work remotely for my US employer on it?', 'The tourist eVisa is a visitor visa and does not authorise employment. Short business meetings as a visitor are fine; working in the Kingdom is not.')]},
'saudi-visa-for-indian-citizens': {'mins': 7, 'facts': ['An Indian passport alone is not eVisa-eligible - beware sites selling one against it', 'UAE and GCC residents apply on the GCC-resident eVisa route', 'A used US, UK or Schengen visa opens the visa-on-arrival route', 'Sponsored family visit visas cover relatives in the Kingdom'], 'faq': [('I am Indian and live in Dubai. What is my route?', 'The GCC-resident eVisa. Your Emirates residency qualifies you; you need six months on your passport and three months on your residency. It is the same one-year multiple-entry visa, Umrah included outside Hajj.'), ('My parents in India want to visit me in Saudi Arabia. How?', "If you hold Saudi residency, you sponsor a family visit visa for them. If you are all based in the UAE and travelling together, check each person's own route - yours may differ from theirs."), ('Can I get a Saudi work visa through this site?', 'No, and we will not pretend otherwise. Work and residence visas run through employers and the embassy system. We handle visits, Umrah, family and business-visit travel.')]},
'evisa-vs-embassy-visa': {'mins': 6, 'facts': ['The eVisa is digital, issued by email against your passport - no sticker, no appointment', 'Embassy visas remain the route for work, residence and uncovered cases', 'Both produce the same record at the border; only the journey to get them differs', "The eVisa's strictness about exact details is why a specialist check matters"], 'faq': [("Is an eVisa a 'real' visa?", 'Completely. It is issued by the same authority, recorded on the same system and checked the same way at the border. Only the delivery - digital instead of a passport sticker - is different.'), ('Why do some nationalities still use embassies?', 'The eVisa list covers 72 passports. Everyone else, and categories like employment and residence, use the mission route or sponsored routes. It is about which door your case fits, not a lesser visa.'), ('My online application was refused. Embassy next?', 'Possibly - a refusal sometimes needs a human review of the file. Talk to us first with the details; many refusals trace back to a fixable document problem.')]},
'can-you-extend-a-saudi-evisa': {'mins': 6, 'facts': ['Tourist eVisa stays cannot be extended - the terms are fixed at issue', 'Multiple-entry holders can exit and return, but the 180-day yearly ceiling still applies', 'Sponsored family visit visas CAN be extended by the host through Absher', 'Overstaying draws a fine per day and can affect future applications'], 'faq': [('Can I pay a fee to extend my tourist eVisa?', 'No such fee exists. There is no extension product for the tourist eVisa at any price - anyone selling one is not selling a real thing.'), ('I leave and re-enter. Does my 90 days reset?', 'Yes, a new visit starts a new 90-day allowance on a multiple-entry visa - but your days still accumulate toward the 180-day yearly maximum.'), ('What if I overstay by accident?', 'Leave as soon as you realise, and expect a fine for each day over, payable before departure. Long or repeated overstays can lead to detention and re-entry bans, so treat the date as hard.')]},
'saudi-visa-sponsor-explained': {'mins': 7, 'facts': ['A sponsor is a citizen, resident or company inside Saudi Arabia who hosts your visit', 'The sponsor obtains an approved invitation with a reference your application attaches to', 'Family visits need relationship proof - birth or marriage certificates', 'Details on the invitation and your passport must match exactly'], 'faq': [('Can my friend in Saudi Arabia sponsor me?', 'If they are a Saudi citizen, yes - citizens can issue personal visit invitations. A friend who is themselves on a visit visa cannot sponsor anyone.'), ('My sponsor has the invitation. What do I send you?', 'The invitation reference, your passport, a compliant photo, and relationship documents for family visits. We check the invitation against your passport before filing - mismatches are the main cause of delay.'), ('Does the sponsor pay for my visa?', "The sponsor's part is the invitation, which is theirs to arrange. The application fees on your side are confirmed in writing before you pay anything, as with every route on this site.")]},
'gcc-unified-tourist-visa': {'mins': 6, 'facts': ['Approved in principle by all six GCC states; no confirmed launch date at the time of writing', 'It cannot be bought or applied for yet - offers to sell it are not real', 'It targets multi-country Gulf trips; a Saudi-only trip gains nothing from waiting', 'GCC residents already hold a working route: residency opens the Saudi eVisa'], 'faq': [('When does the GCC unified visa launch?', 'No official date has been confirmed. Officials have spoken about a pilot phase, but applications are not open. We will update this page and our checker the moment the official platform opens.'), ('Should I wait for it before booking my Saudi trip?', 'No. The current Saudi eVisa is a one-year multiple-entry visa that already covers most visitors, and the unified scheme would not improve a Saudi-only trip.'), ('Will it include Umrah?', "Unknown until the official mechanics are published. Umrah today runs on the tourist eVisa outside Hajj season or the dedicated Umrah visa, and we will confirm the unified visa's position when it is official.")]},
"saudi-evisa-validity-90-day-stays": {
  "mins": 6,
  "facts": [
    "Validity is one year from issue - that is your window to enter, not a year inside the Kingdom",
    "Each stay is up to 90 days, and stays across the year add up to a 180-day maximum",
    "The tourist eVisa stay cannot be extended from inside Saudi Arabia",
    "Some nationalities receive a single-entry 30-day version instead - it is printed on the visa",
  ],
  "faq": [
    ("My visa is valid for a year. Can I stay the whole year?", "No. Validity is the window in which you may enter. Each stay is limited to 90 days, and your stays across the year may not exceed 180 days in total."),
    ("Does leaving and re-entering reset my 90 days?", "A new entry starts a new stay of up to 90 days while your visa remains valid - but the 180-day yearly total keeps counting, and repeated border runs attract attention."),
    ("What happens if I overstay by a few days?", "Overstays are fined per day and recorded against you, which can affect future applications. If something goes wrong mid-trip, contact us before your stay expires - most situations have a lawful answer when handled early."),
  ],
},
"first-trip-to-saudi-arabia": {
  "mins": 7,
  "facts": [
    "Tourist women are not required to wear an abaya or cover their hair - modest dress is the working rule",
    "Alcohol is prohibited everywhere in the Kingdom, in any quantity",
    "The weekend is Friday and Saturday, and shops pause briefly at prayer times",
    "Cards and contactless payment are accepted almost everywhere",
  ],
  "faq": [
    ("Can I take photos in Saudi Arabia?", "Yes, of landmarks, landscapes and your own group. Ask before photographing people, and never photograph military or government sites or officials."),
    ("Is Saudi Arabia safe for tourists?", "It is one of the region's lowest-crime destinations for visitors. Ordinary awareness applies as anywhere; respecting local customs is what keeps interactions warm."),
    ("What should I pack differently for Saudi Arabia?", "Modest, loose clothing in breathable fabrics, a layer for aggressively air-conditioned interiors, and sun protection. At religious sites, women should carry a scarf for entering mosque areas."),
  ],
},
"umrah-visa-vs-hajj-visa": {
  "mins": 6,
  "facts": [
    "Umrah can be performed most of the year; Hajj happens once a year on fixed dates",
    "Umrah is possible on a tourist eVisa outside Hajj season, or on a dedicated Umrah visa",
    "Hajj is only ever performed on an official Hajj visa through authorised channels",
    "Performing Hajj on the wrong visa brings fines, deportation and bans",
  ],
  "faq": [
    ("Can I perform Hajj on a tourist eVisa?", "No - never. Hajj requires a dedicated Hajj visa obtained through the official channels for your country of residence. Anyone offering otherwise is putting you at serious risk."),
    ("Which visa is better for Umrah?", "If you are eVisa-eligible, the tourist eVisa is usually simplest and also covers touring. If not, the dedicated Umrah visa arranged through official platforms and licensed operators is your route."),
    ("When should I start preparing for Hajj?", "Months ahead. Places are quota-limited and allocated in advance through official channels, so begin as early as the system for your country allows."),
  ],
},
"saudi-single-entry-vs-multiple-entry": {
  "mins": 5,
  "facts": [
    "Most of the 72 eligible nationalities receive the 1-year multiple-entry eVisa",
    "14 of the 72 receive a single-entry version with a 30-day stay instead",
    "Which version applies is set by your passport - it cannot be chosen or upgraded",
    "A single-entry visa ends the moment you leave Saudi Arabia",
  ],
  "faq": [
    ("Can I upgrade a single-entry eVisa to multiple-entry?", "No. The version is determined by your nationality at issuance. If your plans need two entries, you would apply again for the second entry or ask us whether another route fits better."),
    ("How do I know which version I received?", "It is printed on the issued visa: the number of entries and the permitted stay. Check it the day it arrives - not at the airport."),
    ("I am one of the 14 nationalities. Is the single-entry visa still worth it?", "For a single continuous trip of up to 30 days, yes - it covers the whole visit. It only becomes a problem when plans assumed multiple entries, which is why we flag it before you apply."),
  ],
},
"saudi-evisa-children-families": {
  "mins": 6,
  "facts": [
    "Every child, including infants, needs their own visa on their own passport",
    "Under-18s must travel with a parent or legal guardian",
    "Family applications can be submitted together so the files travel as a group",
    "Each application carries its own official fee - there is no family bundle",
  ],
  "faq": [
    ("Does my baby need a visa for Saudi Arabia?", "Yes. Every traveller of every age needs their own eVisa, issued against their own passport. If your child has no passport yet, apply for that first - it needs six months of validity like any other."),
    ("Can my child travel with just one parent?", "Yes, this is common. Carry the child's birth certificate and a signed consent letter from the other parent - it is not always requested, but airlines and border officers may ask, and it costs nothing to carry."),
    ("Is there a family discount on eVisa fees?", "No - each application is charged individually, because each produces its own visa and its own included medical insurance policy."),
  ],
},
"which-saudi-visa-do-you-need": {
  "mins": 7,
  "facts": [
    "Your route is decided by your passport and your residency - in that order",
    "GCC residents can apply on their residency, whatever their nationality",
    "A used US, UK or Schengen visa can open the door even when your passport cannot",
    "Hajj is the one journey that always needs its own official visa",
  ],
  "faq": [
    ("I am visiting family in Saudi Arabia. Do I need a family visit visa?", "Not always. If you qualify for the tourist eVisa - by passport or by GCC residency - you can visit family on it. The sponsored family visit visa is the route for travellers who do not qualify for the eVisa."),
    ("Can I look for work on a tourist or visit visa?", "No. Visit visas never allow employment, and working on one puts both you and the host at risk. Saudi employment is arranged by the employer through official channels before you travel."),
    ("My situation does not match any of the boxes. What should I do?", "Use the eligibility checker first - it covers all 197 nationalities. If your case is still unclear, the free consultation exists for exactly that: tell us your passport, where you live and why you are travelling, and we will name your route."),
  ],
},
"saudi-evisa-application-mistakes": {
  "mins": 7,
  "facts": [
    "Your application is checked against your passport exactly as written - one wrong character can stall it",
    "A typo in your email address is a top cause of 'my visa never arrived'",
    "Every mistake on the common list is fixable for free before submission - few are fixable after",
    "Never run two applications in parallel through different agents",
  ],
  "faq": [
    ("I typed my passport number wrong and already submitted. What now?", "Tell us straight away. Some details cannot be amended after submission, and the honest options depend on your route - but a second blind application almost always makes things worse, so get advice before spending again."),
    ("Can a photo really get an application refused?", "Yes - the photo is the most common single cause of delay and refusal we see. A fresh, plain-white-background photo taken for this application is the cheapest insurance there is."),
    ("Does a document check slow my application down?", "By hours at most, and it removes the errors that cost days. Files we check are decided without the query-and-resubmit cycle that unchecked files often go through."),
  ],
},
"saudi-evisa-rejected": {
  "mins": 6,
  "facts": [
    "A refusal is a decision about one application - it is not automatically a ban",
    "Most tourist refusals are data, photo or eligibility errors, not security decisions",
    "Reapplying with the same error in the file usually produces the same answer",
    "The official fee is not refunded on a refusal - identifying the cause first protects your money",
  ],
  "faq": [
    ("Does a refused eVisa mean I can never visit Saudi Arabia?", "No. For the common fixable causes - mismatched details, photo faults, wrong route - a corrected application or a different route such as a sponsored visit visa may still succeed. A refusal does stay on your record, so the next application should be prepared properly."),
    ("How soon can I apply again after a refusal?", "There is no benefit to rushing. Identify the cause first: a corrected file can go in as soon as it is right, while a record issue may need time or a different route entirely."),
    ("Will I get my money back after a refusal?", "The official fee is the authority's charge for processing and is not returned on a refusal. If the refusal was caused by an error our team made, we re-apply at no service cost or refund our service fee - see the Refund Policy."),
  ],
},
"saudi-evisa-insurance": {
  "mins": 5,
  "facts": [
    "The official eVisa fee includes the mandatory medical insurance - it is not an add-on",
    "The policy is issued with your visa by the appointed insurer",
    "It is medical cover for the trip - not cancellation, baggage or general travel insurance",
    "Keep the policy document with your visa and passport while you travel",
  ],
  "faq": [
    ("Do I need to buy insurance separately for a Saudi eVisa?", "No - the mandatory medical policy is included in the official fee and issued with your visa. You only need your own policy if you want wider cover, such as cancellation or baggage protection."),
    ("Where is my insurance policy?", "It is delivered with your eVisa documents. If we handled your application and you cannot find it, message us and we will resend the documents."),
    ("Does the included insurance cover pre-existing conditions?", "It is emergency medical cover for the trip under the insurer's terms. If you need cover for a pre-existing condition, take a personal travel policy that includes it."),
  ],
},
"saudi-evisa-eligible-countries": {
  "mins": 8,
  "facts": [
    "72 nationalities can apply for the Saudi tourist eVisa fully online",
    "The eVisa is valid 1 year, multiple entry, up to 90 days per visit",
    "14 of the 72 nationalities receive a single-entry, 30-day version instead",
    "Not on the list? GCC residency or a used US/UK/Schengen visa can still open a route",
  ],
  "sections": [
    ("How the 72-country list is grouped", [
      "The list is not one flat group. Most of the 72 nationalities receive the standard tourist eVisa: one year of validity, multiple entries, and stays of up to 90 days per visit. A smaller group of 14 nationalities is offered a single-entry version with a 30-day stay instead. Both are applied for the same way - the system simply issues the version your passport qualifies for.",
      "Eligibility follows your passport, not where you live. An Indian passport holder living in London is treated as an Indian applicant; a British passport holder living in Dubai is treated as a British applicant. Your residence permit only matters for the separate GCC-resident route.",
    ]),
    ("If your country is not on the list", [
      "A passport outside the 72 is not the end of the road. Three routes cover most other travellers:",
    ], [
      "GCC residents: if you hold a residence permit for the UAE, Qatar, Kuwait, Bahrain or Oman, you can apply for an eVisa on that residency, whatever your nationality",
      "US, UK or Schengen visa holders: a valid visa for one of these that you have already used to enter that country usually qualifies you for visa on arrival, and often for an eVisa assessment",
      "Sponsored visit visas: family, personal and business visit visas arranged through a host in Saudi Arabia, which is how most non-eligible nationalities travel",
      "Embassy application: the fallback for cases none of the above fits - slower, but always available",
    ]),
  ],
  "faq": [
    ("Does the tourist eVisa let me perform Umrah?", "Yes, outside the Hajj season. You book your Umrah time slots on the official Nusuk app after your visa is issued. Hajj itself always requires a dedicated Hajj visa through official channels."),
    ("I have two passports. Which one counts?", "The passport you apply and travel with. Apply with the stronger passport if one of them is on the 72-country list, and travel on that same passport."),
    ("Can I apply for my whole family at once?", "Each traveller needs their own application and their own eVisa, including children. Families can submit them together so the applications travel through the system as a group."),
  ],
},
"saudi-tourist-visa-requirements": {
  "mins": 8,
  "facts": [
    "Passport valid for at least 6 months from your entry date",
    "One recent photo on a plain white background",
    "No hotel booking or flight ticket needed for the standard eVisa application",
    "The official fee includes the mandatory medical insurance for your stay",
  ],
  "sections": [
    ("The photo rules that actually get checked", [
      "More applications stall over the photo than over anything else. The photo must be recent, taken against a plain white background, with your full face visible and looking straight at the camera. Head coverings worn for religious reasons are fine as long as the face is fully visible; tinted glasses and heavy shadows across the face are the usual reasons for a re-ask.",
      "A phone photo is acceptable if it is sharp, evenly lit and cropped to show head and shoulders. Blurry scans of old passport photos are the most common document problem we see, and the easiest to avoid.",
    ]),
    ("Names, dates and the passport scan", [
      "Your application details must match your passport exactly - spelling of names, passport number and date of birth. A single transposed digit in the passport number is enough to make the issued eVisa unusable at the border, which is why a specialist checks the scan against the form before submission rather than after.",
      "Scan or photograph the full passport information page: all four corners visible, no fingers covering the machine-readable strip at the bottom, and no glare. If the strip cannot be read, the application usually comes back for a better copy.",
    ], [
      "Passport valid 6+ months from entry, with a blank page for stamps",
      "Name spelling identical to the passport's machine-readable zone",
      "Photo: recent, white background, full face, no tinted glasses",
      "Children: their own passport and their own application",
    ]),
  ],
  "faq": [
    ("Do I need travel insurance as well?", "No separate policy is needed for the eVisa itself - the mandatory medical insurance is bundled into the official fee and issued with your visa. You may still choose extra cover for luggage or cancellations."),
    ("My passport expires in 5 months. Can I apply?", "Not safely. The rule is 6 months of validity from your entry date, and airlines check it at boarding. Renew the passport first, then apply with the new one."),
    ("Do I need a confirmed hotel booking?", "No. The standard tourist eVisa application does not ask for hotel bookings or flight tickets. You can book everything after the visa is issued."),
  ],
},
"saudi-visa-processing-time": {
  "mins": 7,
  "facts": [
    "Straightforward eVisa cases are usually decided within a few working days",
    "Document problems - photo, scan quality, name mismatch - cause most delays",
    "Express handling speeds up our checking and submission, not the authority's decision",
    "Apply 2-3 weeks before travel to leave room for any re-checks",
  ],
  "sections": [
    ("Where the time actually goes", [
      "An application passes through three clocks, and only one of them is the Saudi authority's. The first is preparation: your documents being checked and the form prepared - with a specialist this is normally same-day. The second is submission and payment of the official fee. The third is the authority's own assessment, which for a clean tourist eVisa case is usually a few working days.",
      "When people say their visa 'took two weeks', it is almost always the first clock that stretched: a photo rejected and re-taken, a passport scan re-requested, a name corrected. Those loops are exactly what a document check before submission is designed to remove.",
    ]),
    ("What slows an application down", [
      "The same handful of causes accounts for nearly every delay we see:",
    ], [
      "Photo rejected: wrong background, shadows, or a scan of an old photo",
      "Name or number mismatch between the form and the passport",
      "Passport validity under 6 months discovered late",
      "Peak seasons - Ramadan, Hajj and Saudi public holidays stretch every queue",
      "Extra assessment: some applications are simply selected for a closer look, which adds days and is outside anyone's control",
    ]),
  ],
  "faq": [
    ("Can I pay extra to make the authority decide faster?", "No - no agent can speed up the authority's decision, and anyone who promises that is misleading you. Express handling only guarantees your application is checked and submitted first by our team."),
    ("My flight is in 5 days and I have not applied. Is it too late?", "Not necessarily. A clean case is often decided within a few working days, but there is no slack for a document problem. Apply immediately, choose express handling, and do not book non-refundable extras until the visa is in hand."),
    ("How will I know it is approved?", "Your eVisa is issued electronically against your passport - there is no stamp or sticker to collect. We send you the issued visa, and you can also follow every stage on the tracking page with your reference."),
  ],
},
"umrah-on-tourist-visa": {
  "mins": 8,
  "facts": [
    "Umrah is allowed on the tourist eVisa outside the Hajj season",
    "Umrah and Rawdah time slots are booked on the official Nusuk app",
    "The tourist eVisa never covers Hajj - Hajj needs its own official visa",
    "You can enter through any international airport and travel between Makkah and Madinah freely",
  ],
  "sections": [
    ("Booking your Umrah on Nusuk", [
      "The visa gets you into the country; your Umrah itself is scheduled on Nusuk, the official permit platform. After your eVisa is issued, register on the Nusuk app with your visa details and book an Umrah permit for your chosen date and time. Permits for the Rawdah in Madinah are also booked there and release in limited numbers, so book as early as the system allows.",
      "Arrive at the Grand Mosque within your booked slot and keep the permit visible on your phone - staff check it at the entrances used for Umrah pilgrims. Outside your Umrah slot you can still visit and pray in the mosque as a regular visitor.",
    ]),
    ("When the tourist eVisa does not cover Umrah", [
      "There are two hard limits. First, the Hajj season: as Hajj approaches, Umrah entry on tourist visas pauses and Makkah is restricted to Hajj pilgrims with official Hajj permits. If your trip falls in that window, a tourist eVisa will not get you to Makkah, whatever an agent tells you.",
      "Second, intention: the tourist eVisa covers Umrah, visiting the Prophet's Mosque and tourism. It does not cover Hajj, paid work, or studying - each of those has its own visa route.",
    ], [
      "Umrah on tourist eVisa: allowed most of the year, Nusuk permit required",
      "Hajj on tourist eVisa: never - official Hajj visa only",
      "Umrah during the Hajj-season pause: not possible on a tourist visa",
      "Working or studying on a tourist eVisa: not permitted",
    ]),
  ],
  "faq": [
    ("Can women perform Umrah on a tourist eVisa?", "Yes. Under the current rules women can hold the tourist eVisa and perform Umrah without travelling with a mahram. Many women travel in small groups for convenience, but it is not a visa requirement."),
    ("Do I need to book hotels before applying?", "No. The eVisa application does not require hotel bookings. Book your Makkah and Madinah hotels after the visa is issued - but for Ramadan and peak weeks, book rooms early because the cities fill up."),
    ("Can I visit Madinah first, then Makkah?", "Yes - the order is up to you. Many visitors land in Madinah, spend a few days there, then take the Haramain high-speed train to Makkah for Umrah."),
  ],
},
"saudi-transit-stopover-visa": {
  "mins": 7,
  "facts": [
    "Stopover visas run for 48 or 96 hours, tied to a Saudia or flynas ticket",
    "The visa is requested as part of the flight booking, not as a separate application",
    "One entry: it covers a single stopover in Saudi Arabia on that journey",
    "Enough time to leave the airport, see a city and sleep in a hotel",
  ],
  "sections": [
    ("48 or 96 hours - which one will you get?", [
      "The stopover visa is issued alongside an eligible Saudia or flynas booking that connects through a Saudi airport. Which length you receive - 48 or 96 hours - depends on your itinerary and fare: the length of your connection and the booking channel decide it, and it is shown during booking, before you pay. A 96-hour visa comfortably covers two nights; 48 hours suits one night and a day of sightseeing.",
      "The important detail: the visa is applied for during the flight booking flow on the airline's own site. It is not something you add afterwards through a separate portal, so decide before you complete the booking.",
    ]),
    ("Making the most of a stopover", [
      "Jeddah connections put you an hour from Al-Balad's coral-stone old town and the Red Sea corniche. Riyadh connections suit the National Museum, Diriyah's mud-brick palaces and Kingdom Centre's sky bridge. Both airports have fast road links into the city, and your stopover visa covers hotel stays like any other visit visa.",
      "Keep the basics in order: your onward flight time governs everything, so stay within reach of the airport on departure day, and keep your passport and onward boarding pass with you - hotels will ask for both.",
    ]),
  ],
  "faq": [
    ("Is the stopover visa free?", "The visa is arranged as part of the airline booking; depending on the fare, a modest service and insurance charge can apply. What you will pay is shown during booking before you confirm - there is no separate fee at the airport."),
    ("Can I leave the airport on a stopover visa?", "Yes - that is the point of it. You can clear immigration, stay in a hotel and tour the city within your 48 or 96 hours."),
    ("My connection is only 10 hours. Is it worth it?", "For a short connection most travellers stay in the airport or take a brief city trip in Jeddah or Riyadh. The visa makes sense from roughly a 12-hour connection upward, when a hotel night and real sightseeing fit comfortably."),
  ],
},

"saudi-visa-on-arrival": {
  "mins": 7,
  "facts": [
    "Open to eVisa-eligible nationals, GCC residents and used US/UK/Schengen visa holders",
    "Issued at the airport on arrival - payment is by card, not cash",
    "Eligible nationals receive the same 1-year multiple-entry framework as the eVisa",
    "If you are unsure of your eligibility, the online eVisa removes the airport risk",
  ],
  "sections": [
    ("What happens at the airport desk", [
      "On arrival, go to the visa-on-arrival counters before immigration. The officer checks your passport and, for the US/UK/Schengen route, the visa you are relying on and its entry stamp. You pay the official fee by card - it includes the mandatory medical insurance - your biometrics are taken, and the visa is issued electronically against your passport.",
      "In a quiet hour the whole stop takes minutes. At peak arrival banks it can take considerably longer, which is the trade-off against applying online in advance.",
    ]),
    ("Who should NOT rely on visa on arrival", [
      "Visa on arrival is a privilege the officer confirms at the desk, not a pre-approval. If your US/UK/Schengen visa has never been used to enter its country, if your passport validity is borderline, or if your nationality's status is one of the 30-day single-entry cases, an advance eVisa is the safer instrument - you board your flight already knowing the answer.",
    ], [
      "Used US/UK/Schengen visa: the entry stamp in your passport is the proof - carry the passport that holds it",
      "Passport validity: 6 months minimum, checked at the desk",
      "Payment: card only - have a working international card ready",
      "Families: every traveller, children included, is processed individually",
    ]),
  ],
  "faq": [
    ("Is visa on arrival the same as the eVisa?", "For eligible nationalities it grants the same tourist permission - one year, multiple entry, 90 days per visit. The difference is only when it is issued: at the airport instead of before you fly."),
    ("What if I am refused at the desk?", "You would not enter Saudi Arabia on that trip and the airline manages your return. It is rare for clearly eligible travellers, which is why anyone with a borderline case should apply online first."),
    ("Can GCC residents get visa on arrival?", "GCC residents are one of the eligible groups, but the online eVisa on your residency is usually smoother - it avoids the desk queue entirely."),
  ],
},
'saudi-visa-gcc-residents': {'mins': 7, 'facts': ['Residents of the UAE, Qatar, Kuwait, Bahrain and Oman qualify on residency, whatever their passport', 'Two conditions only: passport valid 6+ months, residency valid 3+ months', 'Profession no longer decides eligibility - that condition was removed', 'GCC citizens do not need this route: they enter Saudi Arabia visa-free'], 'faq': [('I have a GCC visit visa, not residency. Do I qualify?', 'No. The route is for legal residents of a GCC country. A tourist or visit visa for a Gulf country confers no Saudi eligibility - your routes are then the passport-based ones or a sponsored visa.'), ('Does my family qualify through my residency?', 'Each person qualifies through their own residency. A spouse or child who also holds GCC residency applies the same way; a relative visiting you in the Gulf does not.'), ('Can I drive to Saudi Arabia on this visa?', "Yes. The eVisa is valid at land borders as well as airports, which is how many Gulf residents use it - the causeway traffic and the Kingdom's land crossings included.")]},


"saudi-travel-etiquette-guide": {
  "mins": 8,
  "facts": [
    "Dress modestly in public: shoulders and knees covered; abaya is not required for visitors",
    "Alcohol is strictly prohibited everywhere in Saudi Arabia",
    "Ask before photographing people; never photograph military or airport security areas",
    "Non-Muslims cannot enter Makkah; Madinah's mosque precincts are for worshippers",
  ],
  "sections": [
    ("The daily rhythm: prayer times and Fridays", [
      "Five times a day, life briefly pauses for prayer. Shops may close for a short period around prayer times, especially in smaller towns, and Friday is the week's holy day - many businesses open later, after Friday prayers. Plan around it loosely and it never becomes a problem: attractions list their prayer-time closures, and the pause is a good excuse for coffee.",
      "During Ramadan the rhythm inverts: days are quiet, and after sunset the cities celebrate. Eating in public during fasting hours is discreetly avoided by visitors out of respect, though hotels serve non-fasting guests.",
    ]),
    ("Photography, privacy and phones", [
      "Saudi Arabia is photogenic and mostly welcoming to cameras - landscapes, architecture and street scenes are fine. The rules are about people and security: ask before photographing individuals (especially women and families), and never photograph military sites, airports' security areas or government installations. Drones require permits; leave yours at home unless you have arranged one.",
    ], [
      "Greetings: a handshake and 'As-salamu alaykum' go a long way; some people prefer not to shake hands across genders - follow their lead",
      "Public behaviour: modest affection only; loud or drunken behaviour is an offence, and there is no alcohol to begin with",
      "Money: cards and phones are accepted almost everywhere; cash is rarely needed",
      "Getting around: Uber and Careem work in the main cities; the Haramain train links Makkah, Jeddah and Madinah",
    ]),
  ],
  "faq": [
    ("Do women visitors have to wear an abaya or cover their hair?", "No. Foreign visitors are not required to wear an abaya or a headscarf in public - modest dress is the expectation. Inside mosques, women cover their hair as a sign of respect, and an abaya is practical there."),
    ("Can non-Muslims visit Madinah?", "Non-Muslims can visit the city of Madinah and its museums and historic areas, but entry into the Prophet's Mosque itself is reserved for Muslim worshippers. Makkah city is closed to non-Muslims entirely."),
    ("Is Saudi Arabia strict about social media posts?", "Normal travel sharing is fine and common. Avoid posts that mock religion, the country or its leadership, and never post photos of identifiable people without consent - the same privacy rule as offline."),
  ],
},

"saudi-visa-photo-requirements": {
  "mins": 7,
  "facts": ["Recent photo, taken within the last 6 months, on a plain white background", "Full face, centred, both eyes open - no filters, no shadows, no glare", "Religious head coverings are fine if the full face stays visible", "A sharp phone photo against a white wall passes - a scanned old photo often fails"],
  "sections": [
    ("What happens when a photo is rejected", ["A rejected photo does not kill the application, but it stops the clock: the case comes back, you upload a new image, and the file rejoins the queue. In a quiet week that costs a day; in Ramadan or Hajj season it can cost several. It is the cheapest delay in the whole process to prevent, and the reason our document check looks at the photo before anything is submitted."]),
    ("Photos for children and infants", ["Children need their own compliant photo on their own application - a parent holding a baby against a white sheet at home is the standard approach for infants, with the adult's hands kept out of frame. School-age children manage the normal rules: white wall, daylight, no favourite cap or sunglasses, however attached they are to them."]),
  ],
  "faq": [
    ("Can I wear hijab in the photo?", "Yes. Head coverings worn for religious reasons are accepted. Your full face - forehead to chin, both sides - must be visible and unshadowed."),
    ("My photo was taken at a studio for another country's visa. Can I reuse it?", "If it is under six months old, on a plain white background and uncropped differently, usually yes. Square-crop versions for other countries are fine as long as the face is large and sharp."),
    ("Smiling or neutral?", "Neutral is safest. A natural closed-mouth expression is accepted; wide grins and tilted heads are what automated checkers dislike."),
  ],
},
"saudi-family-visit-visa-guide": {
  "mins": 8,
  "facts": ["The host in Saudi Arabia starts the application - a citizen or iqama holder", "Core circle: spouse, parents, children and siblings of the host", "Issued as single-entry (up to 90 days) or multiple-entry (up to 90 days per visit)", "Relationship proof - marriage or birth certificates - is the key document"],
  "sections": [
    ("Documents the host needs ready", ["Before starting the request, the host should have their ID or iqama details, your full passport name exactly as printed, and the relationship documents scanned and legible. Names are matched character by character between the request and your passport - a nickname or a reordered name is enough to stall an approval.", "If your relationship documents come from a third country or a third language, certified translation into Arabic or English at this stage saves the most time of any step in the process."]),
    ("What the visitor pays and receives", ["The visitor side pays the official visa fee and the mandatory medical insurance, both confirmed before payment. What comes back is an electronic visa tied to the visitor's passport and the host's request - print a copy for the airline desk and keep the digital version on your phone, like every Saudi eVisa."]),
  ],
  "faq": [
    ("Can a friend sponsor me on a family visit visa?", "No - the family visa is for relatives. Friends use the personal visit visa route, which also runs through a host in Saudi Arabia but is assessed differently."),
    ("Can I work or study on a family visit visa?", "No. It is a visit visa: family time and tourism. Employment and enrolled study each have their own visa categories."),
    ("My host is a resident, not a citizen. Is that fine?", "Yes - legal residents with an iqama host family visit visas in the same way. Their residency must be valid for the duration of the process."),
  ],
},
"can-you-extend-a-saudi-visit-visa": {
  "mins": 7,
  "facts": ["Tourist eVisa stays cannot be extended - exit and re-entry starts a fresh 90 days", "Single-entry family visit visas can be extended by the host via Absher", "Overstay fines are charged per day and collected before departure", "Your 90-day clock is per visit, inside the visa's one-year validity"],
  "sections": [
    ("Planning a long stay the legal way", ["If you know from the start that you want months in the Kingdom, plan the rhythm instead of fighting the rules: the multiple-entry tourist eVisa supports a pattern of stays separated by short exits, and Gulf-based travellers often pair this with their residence in the UAE or Qatar. What matters is that each individual stay stays inside 90 days and each exit and entry is genuine.", "Keep boarding passes and entry stamps tidy - a clean travel pattern is its own argument at any future application."]),
    ("If you have already overstayed", ["Do not wait for it to grow. Overstay fines accumulate daily and are settled at departure or through the passport authorities; longer overstays risk detention and deportation, which damages future Gulf travel far beyond Saudi Arabia. If an emergency - hospitalisation, a cancelled route home - caused the overstay, keep the documents: genuine evidence is considered, silence is not."]),
  ],
  "faq": [
    ("Does leaving for one day reset my 90 days?", "A genuine exit and re-entry starts a new stay period on a multiple-entry visa. Same-day turnarounds done purely as a formality can attract questions - travel like a traveller, not a loophole."),
    ("Can my hotel or an agent extend my tourist visa for a fee?", "No. No agent, hotel or fixer can extend a tourist eVisa - anyone selling that is selling a document the authorities will not recognise."),
    ("What if my flight home is cancelled on day 89?", "Contact the airline and keep the cancellation evidence; a documented disruption is treated very differently from a silent overstay. Rebook the earliest exit and keep every record."),
  ],
},
"saudi-business-visit-visa-guide": {
  "mins": 8,
  "facts": ["A Saudi company starts the process with an official invitation in your name", "Your passport details on the invitation must match your application exactly", "Meetings and conferences yes - hands-on employment needs a work visa", "Multiple-entry versions (6-12 months) are decided at the invitation stage"],
  "sections": [
    ("How long the route takes", ["The invitation approval on the Saudi side is the variable part - days in a well-organised company, longer when chamber attestations queue. Once the invitation is approved and your documents are clean, the application itself moves at the same pace as other visit visas. Companies running a first invitation for a new partner should start three to four weeks before the intended travel date."]),
    ("At the border and in the Kingdom", ["Carry the invitation copy and your employer's letter with your passport - officers can ask what brings you, and the paper answers it. Your visit visa covers your meetings across the Kingdom, so internal travel between Riyadh, Jeddah and the Eastern Province needs no extra permission.", "If the relationship deepens into regular presence, that is the point to discuss work permits and iqamas with the host company - the visit visa is a bridge, not a residence."]),
  ],
  "faq": [
    ("Can I attend a trade fair or conference on this visa?", "Yes - conferences, exhibitions and training are core business-visit purposes. Keep your event registration with your invitation papers."),
    ("Can the Saudi company apply for my whole team?", "Each traveller needs an invitation in their own name, but a company can issue them as a batch for the same visit. Names and passport numbers must be exact on each one."),
    ("Is a business visit visa convertible to a work visa inside Saudi Arabia?", "Generally no - work visas are processed from outside the Kingdom through the employer. Treat the visit as scouting and meetings, and let the work route run its own course."),
  ],
},
"first-time-in-riyadh-guide": {
  "mins": 8,
  "facts": ["Diriyah and the National Museum are the two essential first stops", "The Riyadh Metro's six lines cover the airport, KAFD and main sights", "Edge of the World is a half-day desert trip - best October to March", "Evenings are the city's social prime time; plan sights early, dining late"],
  "sections": [
    ("Neighbourhoods in plain terms", ["Olaya is the central spine - towers, hotels, Tahlia Street's restaurants. KAFD is the sculptural new financial district, worth a walk for the architecture alone. Diriyah in the northwest is the heritage quarter and the city's favourite evening out, while the Diplomatic Quarter is green, calm and cafe-dotted. Distances are large: cluster your day by area rather than zig-zagging.", "For a short trip, stay in Olaya or KAFD and treat Diriyah as your evening destination - that combination covers most first-visit highlights without long cross-city drives."]),
    ("Small logistics that save the day", ["The working week runs Sunday to Thursday, with Friday the main rest day - museums and Diriyah keep visitor hours through the weekend. Prayer times pause some venues briefly; the big attractions publish their daily windows, so check before crossing the city for one stop.", "Cards and phone payments work almost everywhere, ride-hailing is the default, and the airport run needs an honest hour. Riyadh rewards planners - which is exactly the traveller this visa process selects for."]),
  ],
  "faq": [
    ("How many days does Riyadh need?", "Two full days cover the essentials comfortably; three lets you add the Edge of the World without rushing. Many visitors pair Riyadh with AlUla by a short internal flight."),
    ("Is Riyadh safe for tourists?", "It is one of the region's safest capitals for visitors - standard city awareness applies, and the main risks are traffic and summer heat, not crime."),
    ("What should I wear in Riyadh?", "Modest dress in public - shoulders and knees covered. Business settings are formal; Diriyah evenings are smart-casual. Women visitors are not required to wear an abaya."),
  ],
},
"saudi-evisa-or-visa-on-arrival": {
  "mins": 7,
  "facts": ["Same permission either way: 1 year, multiple entry, 90 days per visit", "The eVisa answers every question before you board; arrival answers them at a desk", "Borderline cases - near-expiry documents, mixed routes - belong online", "Airline check-in is smoother with an issued visa in hand"],
  "sections": [
    ("The cost question, answered plainly", ["Both routes carry the same official fee structure, insurance included - choosing arrival does not save the fee, and choosing online does not add a government charge. The only extra an online applicant might pay is a service fee if they use a specialist to check and submit, which buys the document check rather than the visa itself."]),
    ("A two-question decision rule", ["Ask yourself two things. First: is there any paper in my file an officer could query - a visa stamp, a date, a spelling? Second: what happens to my trip if the answer at the desk is no? If either answer makes you pause, the eVisa is your route. If both answers are easy, arrival is a legitimate, designed-for-use option - not a loophole."]),
  ],
  "faq": [
    ("Can I apply online and still be refused at the border?", "An issued eVisa is a real approval - refusals at the border for eVisa holders are rare and usually involve a document mismatch, such as travelling on a different passport than the one the visa was issued to."),
    ("If I am refused visa on arrival, can I apply online from the airport?", "You would normally need to leave on the airline's routing - an online application from the arrivals hall is not a practical rescue. That asymmetry is the whole argument for applying first."),
    ("Which is faster overall?", "Online, for most people: a few days of waiting at home against an airport queue and a small but real uncertainty. Arrival only wins when the trip itself is spontaneous."),
  ],
},
'saudi-visa-fees-explained': {'mins': 6, 'facts': ['The 1 Year Multiple Entry total is USD 300, the 90 Days Multiple Entry USD 200 and the 90 Days Umrah USD 250 - all-in', 'Every total includes the official fee, the mandatory insurance and our service - nothing is added later', 'Other visas are confirmed in writing before payment, because the route and nationality change the figure', 'After submission, the official fee and issued insurance cannot be refunded; our service fee is refunded if our error caused a refusal'], 'faq': [('Is the insurance really included, or added at the end?', 'It is included. Medical insurance is a mandatory part of a Saudi visit visa and is issued in your name as part of the total - there is no separate insurance charge later.'), ('Why is there no price shown for the family visit visa?', "Because its terms are set by the sponsor's invitation - the length and type differ from case to case, so a single published figure would be wrong for most families. Your total is confirmed in writing before you pay."), ('If my visa is refused, do I get all my money back?', 'Not all of it, and any agency that promises otherwise is not being straight with you. Once an application is submitted, the official fee and the issued insurance cannot be returned. If the refusal was caused by our mistake, we re-apply free of charge or refund our service fee.'), ('Do children pay the same as adults?', 'Every traveller, including children, needs their own visa and their own application. Where a visa carries a published total it applies per application; for a family applying together, the combined total is confirmed in writing before payment.')]},
'saudi-arabia-7-day-itinerary': {'mins': 8, 'facts': ['The route runs Riyadh (2 nights) - AlUla (2) - Jeddah (3), flying between each base', 'November to February is the most comfortable window for the whole route', 'Hegra in AlUla and Al-Balad in Jeddah are both UNESCO World Heritage sites', 'The tourist eVisa allows up to 90 days per stay, so a week sits well inside one trip'], 'faq': [('Can I do this route in five days instead of seven?', 'Yes - drop the second Riyadh day and one Jeddah day. Keep the AlUla overnight: Hegra deserves an unhurried morning, and a day-trip version of AlUla is the one cut travellers regret.'), ('Do I need to hire a car for this itinerary?', 'No. Domestic flights cover the long legs, the Haramain train covers Jeddah-Makkah, and ride-hailing apps and taxis handle the cities. A car only becomes useful if you add remote desert stops.'), ('Can non-Muslims follow the whole route?', "Almost all of it. The exception is Makkah, which is open to Muslims only - non-Muslim travellers swap day 7 for Madinah's outer sights or a slower Jeddah day, as the itinerary describes."), ('Which month is best for this trip?', 'November to February. Riyadh and Jeddah are pleasantly warm, AlUla is at its best, and the Red Sea is swimmable. Summer compresses sightseeing into early mornings and evenings.')]},
'money-sim-and-phones-in-saudi-arabia': {'mins': 7, 'facts': ['The riyal is pegged at 3.75 to the US dollar, so the rate never moves', 'Cards and phone payments are accepted almost everywhere in the cities; keep a small cash float for markets and tips', 'Tourist SIMs from STC, Mobily and Zain are sold in airport arrivals and must be registered to your passport', 'Plugs are Type G (the UK-style three-pin), and the unified emergency number is 911 in Riyadh, Makkah and the Eastern Province'], 'faq': [('Which SIM network should I choose?', 'Any of the three works well in the cities. STC generally has the widest coverage if your trip includes long drives or remote areas; otherwise pick the tourist bundle with the data allowance that fits your trip.'), ('Can I just use my home SIM and roaming?', 'You can, and for a very short trip it may be simplest - but roaming data is usually far more expensive than a local tourist SIM, and a Saudi number helps with ride-hailing apps, deliveries and one-time codes.'), ('Do I need cash at all if I have cards?', 'A little. Cards cover the overwhelming majority of spending in the cities, but small shops, some taxis, market stalls and tips still run on cash. One or two hundred riyals in small notes is a sensible float.'), ('Is the exchange rate fixed everywhere?', 'The official peg is fixed at 3.75 riyals to the dollar. What varies is the margin: ATMs use your bank rate, airport kiosks take a wider cut, and paying a card terminal in riyals rather than your home currency avoids the till-side conversion markup.')]},
'is-saudi-arabia-safe-for-tourists': {'mins': 7, 'facts': ['Street crime against tourists is uncommon; the main practical risks are road traffic and summer heat', 'Alcohol is prohibited and drug offences carry severe penalties - the laws apply to visitors in full', 'Most foreign governments advise against travel only to the area near the Yemen border', 'Emergency: 911 in Riyadh, Makkah and the Eastern Province; 999 police and 997 ambulance elsewhere'], 'faq': [('Is Saudi Arabia safe for a solo female traveller?', 'Yes, with the normal awareness any solo traveller uses anywhere. Women travel, work and holiday in Saudi Arabia in large numbers; our dedicated guide to travelling as a woman covers dress, transport and social practicalities in detail.'), ('What is the single biggest danger for tourists?', 'The roads. Driving standards and highway speeds are the most common source of harm to visitors. Belt up, avoid fatigued long-distance driving, and let planes and trains do the long legs where you can.'), ('Can I take photos freely?', 'Landmarks and street scenes, yes. People only with permission, and never military sites, government installations or restricted areas. When in doubt, ask - the question itself is appreciated.'), ('Are there scams I should watch for?', 'Few on the ground. The main one is online: look-alike visa websites charging inflated fees. Check the domain before paying, and verify any issued visa on the official record.')]},
'arriving-in-saudi-arabia-entry-guide': {'mins': 6, 'facts': ['Carry your eVisa printed as well as on your phone - the paper copy speeds up every conversation', 'First-time visitors are fingerprinted and photographed at passport control; it takes under a minute', 'Visa on arrival is an airport-only service for eligible travellers', 'Cash and valuables above SAR 60,000 must be declared at customs'], 'faq': [('How long does immigration usually take?', 'There is no fixed time - it depends on how many flights land together. With an eVisa already in the system, the desk process itself is a few minutes; the queue is the variable, and it grows at peak Umrah periods.'), ('Do I need a printed visa, or is the phone enough?', 'The phone copy is your backup, not your primary. Airlines and officers both handle paper faster, and a printed copy cannot run out of battery at the desk.'), ('Can I enter through a land border on an eVisa?', 'Some land crossings accept eVisa holders, but visa on arrival is airport-only, and the safe planning assumption is to arrive by air. Our entry points page lists which crossings take which visa.'), ('What happens if something in my visa is wrong when I land?', 'Tell the officer before assuming the worst - many mismatches are visible in the system and can be resolved at the desk. If you applied through us, message us with your reference from the airport and we will work the problem with you.')]},
'saudi-arabia-dress-code-for-tourists': {'mins': 6, 'facts': ['Foreign women are not legally required to wear an abaya or a headscarf in public', 'Inside mosques, women cover their hair and wear loose full-cover clothing; men wear long trousers', 'Private beaches, beach clubs and hotel pools follow normal resort rules', 'Jeddah is the most relaxed city; Madinah and smaller towns dress a level more conservatively'], 'faq': [('Will I stand out if I do not wear an abaya?', 'In modern districts of Jeddah and Riyadh, no. In Madinah, smaller towns and traditional souqs you will be in a small minority - not breaking any rule, but many visitors prefer an abaya there for comfort.'), ('Can men wear shorts?', 'Long shorts below the knee pass in casual settings in the big cities, but trousers are the safer default for restaurants, malls and anything official - and they are what most local men wear.'), ('What should I pack to be safe everywhere?', 'Loose, light layers that cover shoulders and knees, one abaya and scarf for women, and a light cover-up for beaches and mosque visits. That kit handles every situation in this guide.'), ('Are the rules different during Ramadan?', 'The law is the same; the sensitivity is higher. Dress a touch more conservatively, and be discreet about eating and drinking in public during daylight hours.')]},
'umrah-packing-list': {'mins': 6, 'facts': ['Install Nusuk and screenshot your permits before you travel - crowds strain the signal', 'While in ihram, toiletries must be unscented, including soap, wipes and lip balm', 'Two sets of ihram for men; women wear their own modest clothing with no set colour', 'A drawstring shoe bag is the small item experienced pilgrims recommend most'], 'faq': [('Can I buy ihram clothing after I arrive instead?', 'Yes - shops around the Haram in Makkah and near the Prophet’s Mosque in Madinah sell everything on this list, usually at fair prices. Many pilgrims buy a second set locally. Bringing one set from home means you are ready if your first Umrah is soon after landing.'), ('How much luggage should I bring?', 'Less than you think. You will walk a lot, hotels involve lifts and crowds, and most pilgrims buy dates and gifts to bring home. One medium case plus a day bag is the common pattern.'), ('Do women need to buy special Umrah clothing?', 'No prescribed outfit or colour exists for women - your normal modest clothing with hijab is correct. Choose breathable fabrics and comfortable closed shoes for the marble floors and distances.'), ('What about my regular medication?', 'Bring it in hand luggage, in original packaging, with a copy of the prescription - especially for anything controlled. Pack enough for the whole trip plus a small reserve in case of delays.')]},
'saudi-arabia-public-holidays': {'mins': 5, 'facts': ['Founding Day is 22 February and National Day is 23 September, both fixed', 'Eid al-Fitr and Eid al-Adha move about eleven days earlier each year with the Hijri calendar', 'Government offices - including visa processing - close for several days around each Eid', 'Makkah and Madinah book out completely around Eid al-Fitr'], 'faq': [('When exactly is Eid this year?', 'The expected window is known well ahead, but the precise day is confirmed by moon sighting shortly before. Use our Hijri converter for the window and build a day of flexibility into fixed plans.'), ('Will my visa application be delayed by an Eid holiday?', 'If it is in progress when the break starts, yes - official processing pauses for the holiday and resumes after. Applying a week or two clear of an Eid avoids the pause entirely.'), ('Is National Day a good time to visit?', 'It is one of the best: a fixed date you can plan around, mild-to-warm weather in most years, and the country celebrating in public with flags, concerts and fireworks.'), ('Are tourist attractions open during the holidays?', 'Mostly yes - malls, restaurants and attractions usually extend hours for the festivals. It is offices, banks and official counters that close.')]},
'vegetarian-vegan-food-saudi-arabia': {'mins': 5, 'facts': ['Falafel, fuul, hummus, moutabel and lentil soup make the traditional table naturally vegetarian-friendly', 'Rice is often cooked in meat stock or ghee - ask before assuming a rice dish is vegetarian', 'Indian restaurants in most cities offer full vegetarian menus by default', "Key phrases: 'ana nabati' (I am vegetarian) and 'bidun lahm' (without meat)"], 'faq': [('Is vegan harder than vegetarian in Saudi Arabia?', 'Somewhat - dairy appears in sauces, desserts and coffee drinks, and ghee is common. In the big cities, dedicated vegan restaurants and delivery-app filters make it straightforward; elsewhere, the mezze repertoire plus clear requests covers most meals.'), ('What can I eat at an iftar buffet during Ramadan?', 'A great deal - iftar spreads are the most varied meals of the year, with soups, salads, mezze, dates, juices and vegetable dishes laid out in quantity. Arrive at sunset with everyone else and eat very well.'), ('Are there vegetarian options near the Haram in Makkah and Madinah?', 'Yes. The streets around both mosques are lined with international, Indian and Pakistani restaurants, and shawarma-era staples like falafel are everywhere. Pilgrims from South Asia have made vegetarian food easy to find in both cities.'), ('What is a safe order anywhere in the Kingdom?', 'Lentil soup, hummus with bread, a fattoush or tabbouleh salad and falafel - available from Riyadh to the smallest highway town, and unmistakably vegetarian.')]},
}
